CREATE OR REPLACE FUNCTION public.hr_wake_erp_revocation_cleanup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE v_secret text; BEGIN SELECT secret_value INTO v_secret FROM public.app_scheduler_secrets WHERE name='internal_cron'; IF v_secret IS NULL OR length(v_secret)=0 THEN RAISE EXCEPTION 'Scheduler credential unavailable'; END IF; PERFORM net.http_post(url:='https://vagiqbespusdxsbqpvbo.supabase.co/functions/v1/offboarding-account-cleanup',headers:=jsonb_build_object('Content-Type','application/json','x-scheduler-secret',v_secret),body:='{}'::jsonb,timeout_milliseconds:=120000); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.hr_wake_erp_revocation_cleanup() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER trg_hr_wake_erp_revocation_cleanup AFTER INSERT ON public.hr_erp_access_revocations FOR EACH ROW EXECUTE FUNCTION public.hr_wake_erp_revocation_cleanup();